#include <iostream>
#include <vector>
#include <string>
using namespace std;

long long walk(vector<vector<long long>>& g, int r, int c, int row, int col, int visited, int total) {
    if (g[row][col] == 2) return visited == total ? 1 : 0;
    long long saved = g[row][col];
    g[row][col] = -1;
    long long count = 0;
    int dr[4] = {1, -1, 0, 0};
    int dc[4] = {0, 0, 1, -1};
    for (int d = 0; d < 4; d++) {
        int nr = row + dr[d], nc = col + dc[d];
        if (nr >= 0 && nr < r && nc >= 0 && nc < c && g[nr][nc] != -1) count += walk(g, r, c, nr, nc, visited + 1, total);
    }
    g[row][col] = saved;
    return count;
}

int main() {
    long long r;
    long long c;
    cin >> r >> c;
    vector<vector<long long>> g(r, vector<long long>(c));
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            cin >> g[i][j];
        }
    }

    int total = 0, startRow = 0, startCol = 0;
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            if (g[i][j] != -1) total++;
            if (g[i][j] == 1) { startRow = i; startCol = j; }
        }
    }
    cout << walk(g, (int)r, (int)c, startRow, startCol, 1, total) << "\n";

    return 0;
}

